@import url('https://fonts.googleapis.com/css2?family=DM+Mono:wght@400;500&family=Lilita+One&family=Nunito:wght@500;700;800;900&display=swap');
:root{--ink:#172a38;--cream:#fff0d4;--gold:#ffbf58;--red:#e55348}
*{box-sizing:border-box}
html,body{width:100%;height:100%;margin:0}
body{background:#15232c;color:var(--cream);font-family:'Nunito',sans-serif;overflow:hidden}
.game-shell{height:100dvh;width:100vw;display:flex;flex-direction:column;padding:0 24px;background:radial-gradient(ellipse at 50% 0,#304758 0,#192c38 55%,#111d25 100%)}
.topbar{height:66px;flex:0 0 66px;display:flex;align-items:center;justify-content:space-between;padding:0 4px}
.brand{display:flex;align-items:center;gap:12px}.brand-mark{width:39px;height:39px;display:grid;place-items:center;border:1px solid #536474;background:#253b49;border-radius:12px;font-size:21px}
.brand b{font:18px 'Lilita One',sans-serif;letter-spacing:1.5px;display:block}.brand small,.top-note,.sound-btn,.bottom-bar,.hud small{font-family:'DM Mono',monospace;letter-spacing:1px}
.brand small{font-size:8px;color:#99a9b0}.top-note{font-size:10px;color:#b9c3c4;display:flex;align-items:center;gap:9px}.top-note i{color:#647782;font-style:normal}.live-dot{height:6px;width:6px;background:#a5cb85;border-radius:50%;box-shadow:0 0 9px #a5cb85}
.header-actions{display:flex;gap:8px}.sound-btn{color:#d8d8c8;background:#253b49;border:1px solid #536474;padding:9px 13px;border-radius:8px;font-size:15px;cursor:pointer}.sound-btn span{font-size:9px;margin-left:4px}.sound-btn:hover{background:#344f60}
.game-frame{position:relative;isolation:isolate;overflow:hidden;flex:1;min-height:0;border:1px solid #c6aa7f;border-radius:5px;background:#91c8d0;box-shadow:0 12px 40px #08151d99}
.game-frame canvas{display:block;width:100%;height:100%;}
.vignette{position:absolute;z-index:2;inset:0;pointer-events:none;background:linear-gradient(180deg,#172b3b76,transparent 23%,transparent 80%,#172b3b38),radial-gradient(ellipse at center,transparent 52%,#19252c55 100%)}
.film-grain{position:absolute;z-index:7;inset:0;pointer-events:none;opacity:.16;background-image:url("data:image/svg+xml,%3Csvg viewBox='0 0 180 180' xmlns='http://www.w3.org/2000/svg'%3E%3Cfilter id='n'%3E%3CfeTurbulence type='fractalNoise' baseFrequency='.84' numOctaves='3' stitchTiles='stitch'/%3E%3C/filter%3E%3Crect width='100%25' height='100%25' filter='url(%23n)' opacity='.5'/%3E%3C/svg%3E");background-size:180px 180px;animation:grain .22s steps(2) infinite}
.film-grain:after{content:"";position:absolute;inset:0;background:repeating-linear-gradient(0deg,#151b1c0c 0 2px,#fff2 3px,#151b1c0a 4px 5px);animation:flicker 5s infinite}
@keyframes grain{0%{background-position:0 0}25%{background-position:-24px 12px}50%{background-position:18px -20px}75%{background-position:-12px -8px}100%{background-position:5px 16px}}
@keyframes flicker{0%,100%{opacity:.42}48%{opacity:.5}50%{opacity:.34}53%{opacity:.48}}
.hud{position:absolute;z-index:3;inset:14px 20px auto;display:grid;grid-template-columns:1fr 1.15fr 1fr;align-items:start;gap:20px;pointer-events:none;text-shadow:0 2px 3px #162633}
.player-hud{display:flex;gap:9px;align-items:center}.hud-icon{font-size:27px;color:#ffdd9c;text-shadow:0 2px 0 #a94c45}.hud small{font-size:8px;color:#f5e9d1;display:block}.hearts{font-size:17px;color:#ed6255;letter-spacing:2px}.stage-hud{text-align:center}.stage-name{font:17px 'Lilita One',sans-serif;letter-spacing:1px;margin:3px 0 7px}.progress,.boss-track{height:5px;border-radius:9px;background:#172a38a3;overflow:hidden}.progress{max-width:180px;margin:auto}.progress i,.boss-track i{height:100%;display:block;background:var(--gold);border-radius:9px;transition:width .2s}.boss-hud{justify-self:end;width:min(100%,190px)}.boss-label{display:flex;flex-direction:column;gap:3px;margin-bottom:7px}.boss-label span{font:12px 'Lilita One',sans-serif;letter-spacing:.5px}.boss-track i{background:#e76a56}
.overlay{position:absolute;z-index:5;inset:0;display:grid;place-items:center;padding:20px;background:#1425307a;backdrop-filter:blur(3px);transition:opacity .25s}.overlay.hidden{opacity:0;pointer-events:none}.overlay-card{width:min(600px,95%);max-height:100%;overflow:auto;text-align:center;padding:clamp(20px,4vh,36px);border:1px solid #e8c99a;border-radius:14px;background:linear-gradient(145deg,#293e49f5,#172b37f5);box-shadow:0 18px 50px #06141ccc}.eyebrow{font:10px 'DM Mono',monospace;letter-spacing:2px;color:#ffcf77}.eyebrow span{padding:0 8px}h1{font:clamp(34px,6vh,54px)/.85 'Lilita One',sans-serif;letter-spacing:2px;margin:15px 0;color:#fff0d4;text-shadow:0 3px #7b463e}h1 em{font-style:normal;color:#ffbf58}.overlay-card>p{font-size:14px;line-height:1.5;color:#d9d4c3;margin:17px 0 20px}.tutorial-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:8px;margin:0 auto 20px;text-align:left}.tutorial-item{min-height:72px;display:flex;align-items:center;gap:10px;padding:10px;border:1px solid #65737a;border-radius:9px;background:#ffffff0b}.tutorial-icon{min-width:49px;min-height:36px;display:grid;place-items:center;padding:0 5px;border:1px solid #bb9c6d;border-bottom-width:3px;border-radius:7px;background:#f2dfbd;color:#263540;font:14px 'DM Mono',monospace}.shoot-icon{color:#bf493f}.tutorial-item b,.tutorial-item small{display:block}.tutorial-item b{font:10px 'DM Mono',monospace;color:#ffcf77}.tutorial-item small{font-size:9px;line-height:1.3;color:#b9c3c4;margin-top:3px}.start-btn{border:0;border-radius:8px;padding:14px 24px;background:linear-gradient(#ffce73,#f5a94d);color:#322a26;font:16px 'Lilita One',sans-serif;letter-spacing:.8px;cursor:pointer;box-shadow:0 4px #a96d3c;transition:transform .12s,filter .12s}.start-btn:hover{filter:brightness(1.08);transform:translateY(-1px)}.start-btn:active{transform:translateY(2px);box-shadow:0 2px #a96d3c}.start-btn b{margin-left:10px}.control-hint{margin-top:16px;color:#b6c0bf;font:9px 'DM Mono',monospace;letter-spacing:.5px}
.toast{position:absolute;z-index:4;top:76px;left:50%;transform:translate(-50%,-10px);padding:10px 20px;background:#283e49ee;border:1px solid #e8c99a;border-radius:20px;font:14px 'Lilita One',sans-serif;letter-spacing:1px;opacity:0;transition:.2s;pointer-events:none}.toast.show{opacity:1;transform:translate(-50%,0)}
.mobile-controls{position:absolute;z-index:4;inset:auto 18px 16px;display:flex;justify-content:space-between;align-items:end;pointer-events:none}.move-controls,.action-controls{display:flex;gap:9px;pointer-events:auto}.mobile-controls button{width:64px;height:58px;display:flex;flex-direction:column;justify-content:center;align-items:center;gap:2px;border:1px solid #fff9;border-bottom:3px solid #8e7655;border-radius:12px;background:#263d49cc;color:#fff0d4;touch-action:none;user-select:none}.mobile-controls button b{font-size:19px}.mobile-controls button small{font:8px 'DM Mono',monospace;letter-spacing:.5px}.mobile-controls button:active{background:#d39656;color:#202d31;transform:translateY(2px);border-bottom-width:1px}
.bottom-bar{height:37px;flex:0 0 37px;display:flex;align-items:center;justify-content:space-between;color:#aab8b8;font-size:9px}.keycap{display:inline-grid;place-items:center;min-width:19px;height:19px;margin:0 3px;border:1px solid #536474;border-radius:4px;color:#e5d4b7}.footer-right span{color:#ffbf58;margin-left:7px}
@media(max-width:700px){.game-shell{padding:0 8px}.topbar{height:52px;flex-basis:52px}.brand{gap:7px}.brand-mark{width:32px;height:32px;font-size:17px}.brand b{font-size:14px}.brand small{font-size:7px}.top-note{display:none}.sound-btn{padding:7px 9px}.sound-btn span{font-size:8px}.game-frame{border-radius:3px}.hud{inset:10px 10px auto;grid-template-columns:1fr 1fr 1fr;gap:6px}.hud-icon{font-size:20px}.hud small{font-size:7px}.hearts{font-size:14px}.stage-name{font-size:13px}.boss-label span{font-size:9px}.boss-hud{width:100%}.tutorial-grid{gap:5px}.tutorial-item{padding:6px;min-height:66px;gap:5px;flex-direction:column;align-items:flex-start}.tutorial-icon{min-width:40px;min-height:26px;font-size:11px}.tutorial-item b{font-size:8px}.tutorial-item small{font-size:8px}.overlay-card{padding:18px 14px}.overlay-card>p{font-size:12px;margin:12px 0}.start-btn{padding:12px 17px;font-size:14px}.control-hint{font-size:8px;margin-top:12px}.bottom-bar{height:28px;flex-basis:28px;font-size:8px}.footer-right{display:none}.mobile-controls{inset:auto 10px 10px}.mobile-controls button{width:54px;height:51px}.toast{top:68px}}
@media(max-height:520px){.topbar{height:44px;flex-basis:44px}.bottom-bar{height:24px;flex-basis:24px}.overlay-card{padding:14px 22px}.eyebrow{font-size:8px}h1{font-size:34px;margin:9px 0}.overlay-card>p{margin:8px 0 12px;font-size:12px}.tutorial-grid{margin-bottom:12px}.tutorial-item{min-height:55px}.start-btn{padding:10px 18px}.control-hint{margin-top:10px}}

